//! Compare the codecs against reference output of php 8.3 (system libgd
//! 2.3.3), generated by gen_ref.php into $GD_REF_DIR. Skipped when the
//! reference directory is absent.

use goro_gd::*;
use std::path::Path;

fn ref_dir() -> Option<String> {
    let d = std::env::var("GD_REF_DIR").ok()?;
    if Path::new(&d).is_dir() {
        Some(d)
    } else {
        None
    }
}

const T: &str = "/home/magicaltux/php-src/ext/gd/tests";

fn dump(im: &Option<Image>) -> Vec<u8> {
    let Some(im) = im else {
        return b"FAIL\n".to_vec();
    };
    let mut s = format!(
        "{} {} {} {} {}\n",
        im.sx,
        im.sy,
        im.true_color as i32,
        if im.true_color { 0 } else { im.colors_total },
        im.transparent
    )
    .into_bytes();
    for y in 0..im.sy {
        for x in 0..im.sx {
            let c = im.get_pixel(x, y);
            s.extend_from_slice(&(c as u32).to_le_bytes());
            if !im.true_color {
                let ci = c as usize;
                let v = true_color_alpha(im.red[ci], im.green[ci], im.blue[ci], im.alpha[ci]);
                s.extend_from_slice(&(v as u32).to_le_bytes());
            }
        }
    }
    s
}

#[test]
fn decoders_match_reference() {
    let Some(r) = ref_dir() else {
        return;
    };
    let mut bad = Vec::new();
    for e in std::fs::read_dir(format!("{}/dec", r)).unwrap() {
        let e = e.unwrap();
        let name = e.file_name().to_string_lossy().into_owned();
        let expected = std::fs::read(e.path()).unwrap();
        let src = name.strip_suffix(".part").unwrap_or(&name);
        let data = std::fs::read(format!("{}/{}", T, src)).unwrap();
        let im = if name.ends_with(".gif") {
            gif_in::create_from_gif(&data)
        } else if name.ends_with(".bmp") {
            bmp::create_from_bmp(&data)
        } else if name.ends_with(".tga") {
            tga::create_from_tga(&data)
        } else if name.ends_with(".wbmp") {
            wbmp::create_from_wbmp(&data)
        } else if name.ends_with(".xbm") {
            xbm::create_from_xbm(&data)
        } else {
            // GD/GD2 support is disabled in the reference libgd
            continue;
        };
        let got = dump(&im);
        if got != expected {
            let eh = String::from_utf8_lossy(
                &expected[..expected.iter().position(|&c| c == b'\n').unwrap_or(0)],
            )
            .into_owned();
            let gh =
                String::from_utf8_lossy(&got[..got.iter().position(|&c| c == b'\n').unwrap_or(0)])
                    .into_owned();
            bad.push(format!("{}: expected [{}] got [{}]", name, eh, gh));
        }
    }
    let _ = goro_gd::take_errors();
    assert!(bad.is_empty(), "{:#?}", bad);
}

fn pal(w: i32, h: i32, n: i32) -> Image {
    let mut im = Image::create(w, h).unwrap();
    for i in 0..n {
        im.color_allocate((i * 37) & 255, (i * 91) & 255, (i * 13) & 255);
    }
    for y in 0..h {
        for x in 0..w {
            let v = ((x >> 2) * 7 + (y >> 1) * 3 + if (x * y) % 5 == 0 { 1 } else { 0 }) % n;
            im.set_pixel(x, y, v);
        }
    }
    im
}

fn tc(w: i32, h: i32) -> Image {
    let mut im = Image::create_true_color(w, h).unwrap();
    im.alpha_blending_flag = 0;
    for y in 0..h {
        for x in 0..w {
            let c = (((x * 3 + y) % 128) << 24)
                | ((x * 5) & 255) << 16
                | ((y * 7) & 255) << 8
                | ((x ^ y) & 255);
            im.set_pixel(x, y, c);
        }
    }
    im
}

#[test]
fn encoders_match_reference() {
    let Some(r) = ref_dir() else {
        return;
    };
    let mut imgs = vec![
        ("p2", pal(17, 9, 2)),
        ("p16", pal(33, 21, 16)),
        ("p256", pal(70, 40, 256)),
        ("p100", pal(130, 77, 100)),
        ("tc", tc(37, 23)),
    ];
    let mut t = pal(20, 20, 5);
    t.color_transparent(2);
    imgs.push(("ptrans", t));
    let mut i = pal(40, 30, 9);
    i.set_interlace(1);
    imgs.push(("pinter", i));
    let mut bad = Vec::new();
    let mut check = |name: String, got: Option<Vec<u8>>| {
        let p = format!("{}/enc/{}", r, name);
        let Ok(exp) = std::fs::read(&p) else {
            return;
        };
        if exp.is_empty() {
            return;
        }
        if got.as_deref() != Some(&exp[..]) {
            bad.push(name);
        }
    };
    for (n, im) in &imgs {
        if !im.true_color {
            check(format!("{}.gif", n), gif_out::image_gif(im));
            check(format!("{}.wbmp", n), wbmp::image_wbmp(im, 1));
            check(format!("{}.xbm", n), Some(xbm::image_xbm(im, b"", 1)));
        }
        check(format!("{}.bmp", n), bmp::image_bmp(im, 0));
        check(format!("{}.rle.bmp", n), bmp::image_bmp(im, 1));
    }
    let p2 = &imgs[0].1;
    let f = format!("{}/enc/My-File.XBM", r);
    check(
        "My-File.XBM".into(),
        Some(xbm::image_xbm(p2, f.as_bytes(), 1)),
    );
    assert!(bad.is_empty(), "{:?}", bad);
}
